src/ui/td.css:
diff --git a/src/ui/td.css b/src/ui/td.css
index 5262a5a..0c4258d 100644
--- a/src/ui/td.css
+++ b/src/ui/td.css
@@ -211,5 +211,27 @@ body.is-paused #tdCanvas, body.is-paused #tdCanvas3d { filter: saturate(0.55) se
 .td-sheet .td-hint-line { padding: 6px 10px; border-left: 4px solid var(--vd-seal); background: rgba(255, 250, 235, 0.7); color: var(--vd-ink); font-weight: 700; }
 .td-review ul { margin: 2px 0 6px; padding-left: 18px; }
 .td-review b { color: var(--vd-jade-ink); }
+/* Accepted art stays inside the scrolling card; the pause card does not instantiate these images. */
+.td-result-crest { display: block; width: 96px; height: 96px; margin: 0 auto 2px; object-fit: contain; }
+.is-lost .td-result-crest { filter: grayscale(0.5) brightness(0.75); }
+.td-sheet .td-result-heading { display: grid; place-items: center; position: relative; height: 84px; margin: 0; text-align: center; color: #fff3d6; font-size: 30px; text-shadow: 0 1px 3px #1c1824; }
+.td-result-heading > span, .td-result-banner { grid-area: 1 / 1; }
+.td-result-heading > span { position: relative; }
+.td-result-banner { display: block; width: min(340px, 100%); height: auto; }
+.td-result-divider { display: block; width: min(280px, 100%); height: auto; margin: 2px auto 6px; }
+.td-sheet img[hidden] { display: none; }
+@media (min-height: 1000px) { .td-result-crest { width: 128px; height: 128px; } }
 /* A short screen (1280 × 720: a won card with 5 words to review was ~730 px): the numbers in two columns, tighter rows. */
 @media (max-height: 800px) { .td-sheet { padding: 12px 18px 14px; } .td-sheet h2 { margin: 0 0 4px; } .td-sheet dt { white-space: nowrap; } .td-sheet dl { grid-template-columns: 1fr auto 1fr auto; gap: 3px 8px; margin: 4px 0 8px; padding: 6px 10px; } .td-sheet button { margin-top: 5px; padding: 6px 12px; } .td-stars i { font-size: 28px; } }
+@media (max-height: 800px) {
+  .td-result-crest { width: 72px; height: 72px; margin-bottom: 0; }
+  .td-sheet .td-result-heading { height: 56px; font-size: 27px; margin: 0; }
+  .td-result-banner { width: 300px; max-width: 100%; }
+  .td-result-divider { width: 240px; margin: 0 auto 3px; }
+  .is-results p { margin: 2px 0 6px; font-size: 13px; line-height: 1.25; }
+  .is-results .td-best { margin: 0 0 3px; }
+  .is-results dl { gap: 2px 8px; margin: 3px 0 5px; padding: 5px 8px; font-size: 13px; line-height: 1.2; }
+  .is-results .td-review { font-size: 13px; line-height: 1.2; }
+  .is-results .td-review ul { display: grid; grid-template-columns: 1fr 1fr; gap: 0 12px; margin: 2px 0; }
+  .is-results button { margin-top: 4px; padding: 5px 12px; font-size: 15px; }
+}
